  client_id text,
  client_name text,
  invoice_id text,
  amount numeric(14,2),
  method text default 'eft',
  reference text,
  status text default 'verified',
  pop_file_id text,
  matched_by text default 'manual',
  match_confidence double precision,
  notes text,
  check (deleted_at is not null or date is not null),
  check (amount is null or amount >= 0.01),
  check (deleted_at is not null or amount is not null),
  check (method is null or method in ('eft', 'cash', 'card', 'cheque', 'other')),
  check (status is null or status in ('verified', 'awaiting_verification', 'rejected')),
  check (matched_by is null or matched_by in ('manual', 'auto_reference', 'auto_amount', 'auto_name')),
  check (match_confidence is null or (match_confidence >= 0 and match_confidence <= 100))
);
