-- Payroll
create table if not exists public.payroll (
  id text primary key default gen_random_uuid()::text,
  created_at timestamptz not null default now(),
  created_by text,
  created_by_name text,
  updated_at timestamptz not null default now(),
  updated_by text,
  updated_by_name text,
  deleted_at timestamptz,
  deleted_by text,
  deleted_by_name text,
  _src text,
  _seed boolean not null default false,
  data jsonb not null default '{}'::jsonb,
  period text,
  employee_id text,
  employee_name text,
  gross numeric(14,2),
  deductions numeric(14,2) default 0,
  net numeric(14,2),
  overtime_hours double precision,
  notes text,
  check (deleted_at is not null or period is not null),
  check (deleted_at is not null or employee_name is not null),
  check (gross is null or gross >= 0),
  check (deductions is null or deductions >= 0),
  check (overtime_hours is null or overtime_hours >= 0)
);
alter table public.payroll add column if not exists created_at timestamptz not null default now();
alter table public.payroll add column if not exists created_by text;
