alter table public.payroll add column if not exists data jsonb not null default '{}'::jsonb;
alter table public.payroll add column if not exists period text;
alter table public.payroll add column if not exists employee_id text;
alter table public.payroll add column if not exists employee_name text;
alter table public.payroll add column if not exists gross numeric(14,2);
alter table public.payroll add column if not exists deductions numeric(14,2) default 0;
alter table public.payroll add column if not exists net numeric(14,2);
alter table public.payroll add column if not exists overtime_hours double precision;
alter table public.payroll add column if not exists notes text;
