alter table public.incidents add column if not exists _seed boolean not null default false;
alter table public.incidents add column if not exists data jsonb not null default '{}'::jsonb;
alter table public.incidents add column if not exists number text;
alter table public.incidents add column if not exists date date;
alter table public.incidents add column if not exists time text;
alter table public.incidents add column if not exists location text;
alter table public.incidents add column if not exists site_id text;
alter table public.incidents add column if not exists type text;
alter table public.incidents add column if not exists severity text default 'low';
alter table public.incidents add column if not exists people_involved text;
alter table public.incidents add column if not exists description text;
alter table public.incidents add column if not exists immediate_action text;
alter table public.incidents add column if not exists root_cause text;
alter table public.incidents add column if not exists corrective_action text;
alter table public.incidents add column if not exists investigation jsonb;
alter table public.incidents add column if not exists reportable boolean;
alter table public.incidents add column if not exists status text default 'open';
